          "text": "import { StockItem } from \"../../generated/ts/inventory/item\";"
        },
        {
          "line": 3,
          "text": ""
        },
        {
          "line": 4,
          "text": "interface Request { payload: string; sku: string; quantity: string }"
        },
        {
          "line": 5,
          "text": "export function runInventory() {"
        },
        {
          "line": 6,
          "text": "  const requests: Request[] = JSON.parse(readFileSync(0, \"utf8\"));"
        },
        {
          "line": 7,
          "text": "  const results = requests.map(request => {"
        },
        {
          "line": 8,
          "text": "    const entity = StockItem.decode(new Uint8Array(Buffer.from(request.payload, \"base64\")));"
        },
        {
          "line": 9,
          "text": "    const sample = StockItem.encode({ sku: request.sku, quantity: Number.parseInt(request.quantity, 10) }).finish();"
        },
        {
          "line": 10,
          "text": "    const fields = { sku: entity.sku, quantity: entity.quantity.toString() };"
        },
        {
          "line": 11,
          "text": "    return { fields, in_stock: BigInt(entity.quantity) > 0n, constructed_payload: Buffer.from(sample).toString(\"base64\") };"
        },
        {
          "line": 12,
          "text": "  });"
        },
        {
          "line": 13,
          "text": "  console.log(JSON.stringify(results));"
        },
